// Questões extras SESI-RS - bloco 2
math.push(...[["Razão e proporção","Uma foto mantém a proporção 4:3. Se a largura é 20 cm, qual deve ser a altura?",["12 cm","15 cm","16 cm","18 cm"],1,"20 ÷ 4 = 5; altura = 3 × 5 = 15 cm."],["Razão e proporção","A razão entre carros e motos em um estacionamento é 7:2. Havendo 14 carros, quantas motos há?",["2","4","6","8"],1,"14 carros correspondem a 2 vezes 7. Logo, motos = 2 × 2 = 4."],["Regra de três","Se 6 cadernos custam R$ 54, quanto custam 10 cadernos no mesmo preço unitário?",["R$ 80","R$ 85","R$ 90","R$ 95"],2,"Cada caderno custa 54 ÷ 6 = 9. Dez custam R$ 90."],["Regra de três","Uma torneira enche 12 L em 3 minutos. Mantido o ritmo, quantos litros enche em 8 minutos?",["24 L","28 L","32 L","36 L"],2,"12 ÷ 3 = 4 L/min. Em 8 min: 4 × 8 = 32 L."],["Regra de três","Um carro percorre 180 km com 15 L. Quantos km percorre com 25 L no mesmo consumo?",["250 km","280 km","300 km","325 km"],2,"180 ÷ 15 = 12 km/L. Com 25 L: 300 km."],["Regra de três","Cinco caixas têm 120 garrafas ao todo. Quantas garrafas há em 8 caixas iguais?",["168","180","192","200"],2,"Cada caixa tem 24 garrafas. 8 × 24 = 192."],["Regra de três","Três pessoas pintam um muro em 12 horas. Supondo produtividade igual, 6 pessoas fariam o mesmo trabalho em quanto tempo?",["4 h","6 h","8 h","9 h"],1,"Dobrar o número de pessoas reduz o tempo pela metade: 12 ÷ 2 = 6 h."],["Regra de três","Uma máquina produz 250 peças em 5 horas. Quantas produz em 9 horas?",["400","450","500","550"],1,"250 ÷ 5 = 50 peças/h. Em 9 h: 450."],["Regra de três","Para 6 pessoas são usados 900 g de massa. Para 14 pessoas, quanto será necessário?",["1.800 g","2.000 g","2.100 g","2.400 g"],2,"900 ÷ 6 = 150 g por pessoa. 14 × 150 = 2.100 g."],["Regra de três","Quatro ônibus transportam 180 estudantes em igual lotação. Quantos estudantes cabem em 7 ônibus iguais?",["280","300","315","340"],2,"180 ÷ 4 = 45 por ônibus. 7 × 45 = 315."],["Equações","Qual número somado a 17 resulta em 45?",["26","27","28","29"],2,"x + 17 = 45; x = 45 − 17 = 28."],["Equações","O triplo de um número é 63. Qual é esse número?",["18","20","21","24"],2,"3x = 63; x = 21."],["Equações","Um número menos 14 é igual a 32. Qual é o número?",["42","44","46","48"],2,"x − 14 = 32; x = 46."],["Equações","O dobro de um número menos 6 é 30. Qual é o número?",["15","16","18","20"],2,"2x − 6 = 30; 2x = 36; x = 18."],["Equações","A soma de um número com seu dobro é 54. Qual é o número?",["16","18","20","24"],1,"x + 2x = 54; 3x = 54; x = 18."],["Equações","Um ingresso custa R$ 12 a mais que outro. Juntos custam R$ 50. Quanto custa o mais barato?",["R$ 17","R$ 18","R$ 19","R$ 20"],2,"x + (x + 12) = 50; 2x = 38; x = 19."],["Equações","Quatro números iguais somados resultam em 76. Qual é cada número?",["17","18","19","20"],2,"4x = 76; x = 19."],["Equações","Metade de um número mais 7 é 19. Qual é o número?",["20","22","24","26"],2,"x/2 + 7 = 19; x/2 = 12; x = 24."],["Gráficos e tabelas","Uma tabela mostra vendas de 18, 25, 22 e 35 unidades em quatro dias. Quantas unidades foram vendidas ao todo?",["90","95","100","105"],2,"18 + 25 + 22 + 35 = 100."],["Gráficos e tabelas","As notas de um aluno foram 6, 7, 8 e 9. Qual é a média?",["7","7,5","8","8,5"],1,"(6 + 7 + 8 + 9) ÷ 4 = 30 ÷ 4 = 7,5."],["Gráficos e tabelas","Um gráfico mostra 40 votos para A, 25 para B e 35 para C. Qual opção recebeu menos votos?",["A","B","C","A e C"],1,"25 é o menor valor, correspondente à opção B."],["Gráficos e tabelas","Uma tabela registra 12°C, 15°C, 14°C, 18°C e 16°C. Qual foi a maior temperatura?",["15°C","16°C","17°C","18°C"],3,"O maior valor da lista é 18°C."],["Gráficos e tabelas","A produção mensal foi 120, 150, 150 e 180 peças. Em quantos meses houve produção de 150 peças?",["1","2","3","4"],1,"O valor 150 aparece em dois meses."],["Gráficos e tabelas","Em uma pesquisa: ônibus 45, carro 30, bicicleta 15 e a pé 10. Quantas respostas foram registradas?",["90","95","100","105"],2,"45 + 30 + 15 + 10 = 100."],["Gráficos e tabelas","Um aluno leu 20 páginas na segunda, 30 na terça e 25 na quarta. Qual foi a média diária?",["20","25","27","30"],1,"(20 + 30 + 25) ÷ 3 = 75 ÷ 3 = 25."],["Gráficos e tabelas","Uma tabela mostra gastos de R$ 80, R$ 95, R$ 70 e R$ 105. Qual a diferença entre o maior e o menor gasto?",["R$ 25","R$ 30","R$ 35","R$ 40"],2,"105 − 70 = R$ 35."],["Tratamento da informação","Em 80 entrevistas, 28 pessoas escolheram a opção A. Que porcentagem isso representa?",["30%","35%","40%","45%"],1,"28 ÷ 80 = 0,35 = 35%."],["Tratamento da informação","Numa pesquisa com 60 alunos, 24 preferem futebol. Qual fração simplificada representa esse grupo?",["2/5","3/5","4/5","5/6"],0,"24/60 simplifica dividindo por 12: 2/5."],["Tratamento da informação","As idades 12, 13, 13, 14 e 15 têm qual moda?",["12","13","14","15"],1,"Moda é o valor que mais se repete. 13 aparece duas vezes."],["Tratamento da informação","Qual é a mediana de 4, 7, 9, 12 e 15?",["7","8","9","12"],2,"Com cinco valores ordenados, a mediana é o terceiro: 9."]]);
port.push(...[["Finalidade comunicativa","“Promoção válida somente hoje: 30% de desconto.” A finalidade principal é:",["Informar e estimular uma compra","Ensinar matemática","Narrar um fato histórico","Explicar uma regra escolar"],0,"A promoção informa uma condição e procura atrair consumidores."],["Finalidade comunicativa","“Não atravesse fora da faixa.” O objetivo é:",["Divertir","Orientar sobre segurança","Anunciar um produto","Contar uma notícia"],1,"A frase orienta uma conduta de segurança."],["Finalidade comunicativa","“Venha participar da feira de ciências neste sábado!” A finalidade é:",["Convidar o público","Proibir a entrada","Relatar o evento depois que ocorreu","Explicar um experimento"],0,"O texto convida o leitor a participar."],["Finalidade comunicativa","“Lave as mãos antes das refeições.” A frase tem como finalidade:",["Dar uma recomendação","Contar uma lembrança","Apresentar uma opinião sobre um filme","Fazer propaganda"],0,"Trata-se de uma orientação de higiene."],["Finalidade comunicativa","“Inscrições abertas até sexta-feira.” A finalidade predominante é:",["Informar um prazo","Narrar uma história","Comparar duas escolas","Descrever uma pessoa"],0,"O enunciado comunica um prazo ao leitor."],["Finalidade comunicativa","“Evite desperdício: sirva apenas o que pretende consumir.” O objetivo é:",["Estimular consumo consciente","Divulgar uma festa","Contar uma piada","Ensinar uma receita"],0,"A frase orienta uma atitude para evitar desperdício."],["Público-alvo","Um aviso começa com “Prezados responsáveis pelos estudantes do 9º ano”. O público-alvo é:",["Motoristas","Familiares ou responsáveis","Turistas","Comerciantes"],1,"O vocativo identifica explicitamente os responsáveis."],["Público-alvo","“Ciclista, use capacete e sinalize suas manobras.” O público-alvo é:",["Pedestres","Ciclistas","Professores","Médicos"],1,"A mensagem se dirige diretamente ao ciclista."],["Público-alvo","Uma campanha diz “Aluno, confira o horário da sua prova”. O leitor principal é:",["O estudante","O diretor apenas","O motorista do ônibus","O público geral"],0,"A palavra “Aluno” identifica o destinatário."],["Público-alvo","Um cartaz em uma clínica diz “Pacientes devem apresentar documento com foto”. A mensagem se dirige principalmente a:",["Pacientes","Funcionários de uma escola","Atletas","Vendedores"],0,"O próprio texto nomeia os pacientes."],["Público-alvo","“Morador, separe o lixo reciclável nos dias corretos.” O público principal é:",["Turistas","Moradores da região","Professores","Crianças pequenas exclusivamente"],1,"O vocativo “Morador” indica quem deve seguir a orientação."],["Público-alvo","Uma mensagem diz “Equipe docente: reunião às 17h”. O público-alvo é:",["Alunos","Professores","Pais","Visitantes"],1,"Equipe docente corresponde aos professores."],["Público-alvo","“Visitantes devem retirar crachá na recepção.” O texto se dirige a:",["Visitantes","Somente funcionários","Somente estudantes","Motoristas de ônibus"],0,"A palavra “Visitantes” identifica diretamente o leitor."],["Fato e opinião","Qual frase expressa uma opinião?",["A ponte foi inaugurada em 2018","O museu abre às 9h","A apresentação foi maravilhosa","O ônibus tem 40 lugares"],2,"“Maravilhosa” expressa avaliação subjetiva."],["Fato e opinião","Qual alternativa apresenta um fato verificável?",["Este é o melhor restaurante","O prédio possui dez andares","A cidade é encantadora","O filme é emocionante"],1,"A quantidade de andares pode ser conferida objetivamente."],["Fato e opinião","Em qual frase há opinião?",["O livro foi publicado em 2024","O livro tem 200 páginas","O livro é extremamente divertido","O autor nasceu no Brasil"],2,"“Extremamente divertido” é um julgamento pessoal."],["Fato e opinião","Qual frase contém um dado objetivo?",["A prova foi terrível","A reunião começou às 14h","A sala é linda","O professor é incrível"],1,"O horário de início é um dado verificável."],["Fato e opinião","Qual alternativa é uma opinião?",["A praça tem três bancos","A praça foi reformada em maio","A praça ficou muito mais bonita","A praça fica no centro"],2,"“Muito mais bonita” depende de avaliação pessoal."],["Fato e opinião","Qual frase é factual?",["O jogo foi emocionante","O time marcou dois gols","O árbitro foi péssimo","A torcida foi maravilhosa"],1,"A quantidade de gols pode ser verificada."],["Fato e opinião","Qual alternativa apresenta opinião?",["A temperatura chegou a 32°C","A cidade tem 100 mil habitantes","O verão é a melhor estação","A escola abriu em 1998"],2,"“Melhor estação” é uma avaliação."],["Narrativa","Em uma narrativa, quem realiza ou participa das ações é chamado de:",["Argumento","Personagem","Título","Legenda"],1,"Personagens são os seres que participam dos acontecimentos."],["Narrativa","“Naquela manhã, Pedro perdeu o ônibus e decidiu ir a pé.” Qual elemento indica tempo?",["Pedro","ônibus","Naquela manhã","ir a pé"],2,"“Naquela manhã” situa o acontecimento no tempo."],["Narrativa","“Ao chegar ao parque, Clara encontrou sua amiga perto do lago.” Qual é o espaço da narrativa?",["O parque","Clara","A amiga","A chegada"],0,"O parque é o local onde ocorre a ação."],["Narrativa","O conjunto de acontecimentos de uma narrativa é chamado de:",["Enredo","Legenda","Tese","Instrução"],0,"Enredo é a sequência de acontecimentos da narrativa."],["Narrativa","Qual frase apresenta uma ação narrativa?",["A água ferve a 100°C","João abriu a carta e ficou surpreso","Recicle o lixo","A escola é importante"],1,"Há personagem e acontecimento em sequência."],["Narrativa","Em “Quando a luz apagou, todos ficaram em silêncio”, o fato que desencadeia a situação é:",["Todos falarem","A luz apagar","O silêncio acabar","A chegada do sol"],1,"A falta de luz inicia a reação dos personagens."],["Narrativa","Qual elemento responde à pergunta “onde aconteceu?” em uma narrativa?",["Espaço","Tempo","Narrador","Tema"],0,"O espaço indica o lugar dos acontecimentos."],["Texto dissertativo","Em um texto dissertativo-argumentativo, a tese é:",["A ideia principal defendida","O nome do autor","Uma lista de personagens","A data de publicação"],0,"Tese é o posicionamento central que será sustentado por argumentos."],["Texto dissertativo","Qual elemento fortalece uma argumentação?",["Razões e evidências relacionadas à tese","Palavras aleatórias","Apenas perguntas","Somente o título"],0,"Argumentos consistentes sustentam a tese com razões, dados ou exemplos."],["Texto dissertativo","A conclusão de um texto argumentativo costuma:",["Retomar a ideia central e fechar o raciocínio","Apresentar personagens novos obrigatoriamente","Mudar totalmente de assunto","Apagar a tese"],0,"A conclusão encerra o raciocínio retomando ou sintetizando a ideia defendida."]]);
